    function depositDelegate(uint256 _amountToken, address _delegator) external returns (bool);

    /// @notice Burns `_amountCs` csMATIC tokens from user and unstake respective amounts of Matic tokens from node.
    function withdraw(uint256 _amountCs) external returns (uint256);

    /// @notice Allows user to claim unstaked tokens.
    function claim(uint256[] calldata _orderIds) external returns (bool);

    /// @notice Burns csMATIC tokens from user and instantly returns Matic tokens to user,
    function instantWithdraw(uint256 _amountCs) external returns (bool);

    /// @notice Performs claiming of rewards & staking of Matic tokens for ClayStack.
    function autoBalance() external returns (bool);
}

